	{
		std::uint8_t  questFile;
		std::uint32_t quest;
		std::uint8_t  infoFile;
		std::uint32_t info;
		std::uint8_t  itemFile;
		std::uint32_t item;
		std::uint16_t count;  // 0: any
	};

